'use strict';

// MODULES //

import isnan from '@stdlib/math-base-assert-is-nan';
import pow from '@stdlib/math-base-special-pow';


// MAIN //

/**
* Evaluates the cumulative distribution function (CDF) for a log-logistic distribution with scale parameter `alpha` and shape parameter `beta` at a value `x`.
*
* @param {number} x - input value
* @param {PositiveNumber} alpha - scale parameter
* @param {PositiveNumber} beta - shape parameter
* @returns {Probability} evaluated CDF
*
* @example
* var y = cdf( 2.0, 1.0, 1.0 );
* // returns ~0.667
*
* @example
* var y = cdf( 4.0, 2.0, 3.0 );
* // returns ~0.889
*
* @example
* var y = cdf( -1.0, 1.0, 1.0 );
* // returns 0.0
*
* @example
* var y = cdf( 0.0, 1.0, 1.0 );
* // returns 0.0
*
* @example
* var y = cdf( NaN, 1.0, 1.0 );
* // returns NaN
*
* @example
* var y = cdf( 1.0, NaN, 1.0 );
* // returns NaN
*
* @example
* var y = cdf( 1.0, 1.0, NaN );
* // returns NaN
*
* @example
* var y = cdf( 1.0, -1.0, 1.0 );
* // returns NaN
*
* @example
* var y = cdf( 1.0, 1.0, -1.0 );
* // returns NaN
*/
function cdf( x, alpha, beta ) {
	var xb;
	if (
		isnan( x ) ||
		isnan( alpha ) ||
		isnan( beta ) ||
		alpha <= 0.0 ||
		beta <= 0.0
	) {
		return NaN;
	}
	if ( x <= 0.0 ) {
		return 0.0;
	}
	// Select the algebraically equivalent form which keeps the intermediate power bounded, thus avoiding overflow to infinity (and a spurious `NaN` result) as `x` grows large...
	if ( x <= alpha ) {
		xb = pow( x / alpha, beta );
		return xb / ( 1.0 + xb );
	}
	return 1.0 / ( 1.0 + pow( alpha / x, beta ) );
}


// EXPORTS //

export default cdf;
